-- Additive compatibility layer: add_ons remains authoritative until application cutover.
CREATE UNIQUE INDEX IF NOT EXISTS idx_extras_add_ons_tenant_id ON add_ons (tenant_id,id);
CREATE TABLE IF NOT EXISTS extra_content (
 tenant_id TEXT NOT NULL,extra_id TEXT NOT NULL,item_name TEXT,short_description TEXT,slug TEXT,
 enable_quantity INTEGER CHECK(enable_quantity IN (0,1)),PRIMARY KEY(tenant_id,extra_id),
 FOREIGN KEY(tenant_id,extra_id) REFERENCES add_ons(tenant_id,id));
CREATE VIEW IF NOT EXISTS extras AS SELECT a.id,a.tenant_id,a.name,a.description AS long_description,a.mews_product_id,
 a.icon_media_asset_id,a.quantity_cap,a.sort_order,a.status,a.created_at,a.updated_at,
 c.item_name,c.short_description,c.slug,c.enable_quantity
 FROM add_ons a LEFT JOIN extra_content c ON c.tenant_id=a.tenant_id AND c.extra_id=a.id;
CREATE TABLE IF NOT EXISTS location_extras (
 tenant_id TEXT NOT NULL,location_id TEXT NOT NULL,extra_id TEXT NOT NULL,
 PRIMARY KEY(tenant_id,location_id,extra_id),FOREIGN KEY(tenant_id,location_id) REFERENCES locations(tenant_id,id),
 FOREIGN KEY(tenant_id,extra_id) REFERENCES add_ons(tenant_id,id));
INSERT OR IGNORE INTO location_extras (tenant_id,location_id,extra_id)
 SELECT tenant_id,location_id,id FROM add_ons WHERE location_id IS NOT NULL;
INSERT OR IGNORE INTO extra_content (tenant_id,extra_id,item_name,short_description,slug,enable_quantity) SELECT a.tenant_id,a.id,NULLIF(json_extract(v.payload_json,'$.itemName'),''),NULLIF(json_extract(v.payload_json,'$.shortDescription'),''),'chocolate-truffles',1 FROM add_ons a LEFT JOIN content_items i ON i.tenant_id=a.tenant_id AND i.kind='add_on' AND i.slug=a.id LEFT JOIN content_revisions v ON v.id=i.current_revision_id AND v.content_item_id=i.id WHERE a.id='6ac372620a9fc691657ebf1e';
